import threading
from pqattest import OneTimeSigner, WOTSOneTimeSigner, keygen, wots_keygen, verify, wots_verify

lp, lpub = keygen()
wp, wpub = wots_keygen()
ls = OneTimeSigner(lp)
ws = WOTSOneTimeSigner(wp)
results = {"l_ok": 0, "w_ok": 0, "l_err": 0, "w_err": 0}

def lamport():
    try:
        s = ls.sign(b"m", context=b"ctx")
        results["l_ok"] += 1
        assert verify(b"m", s, lpub, context=b"ctx")
    except Exception:
        results["l_err"] += 1

def wots():
    try:
        s = ws.sign(b"m", context=b"ctx")
        results["w_ok"] += 1
        assert wots_verify(b"m", s, wpub, context=b"ctx")
    except Exception:
        results["w_err"] += 1

threads = [threading.Thread(target=lamport) for _ in range(16)] + \
          [threading.Thread(target=wots) for _ in range(16)]
for t in threads: t.start()
for t in threads: t.join()
print(results)
assert results == {"l_ok": 1, "w_ok": 1, "l_err": 15, "w_err": 15}, results
print("thread-safety with context: exactly one winner per signer")
EOF
